  102 | /// Render a review for a person to read.
  103 | ///
  104 | /// Reported findings come first, because they are what a human is being asked
  105 | /// to spend attention on. What was investigated and cleared comes after, and it
  106 | /// is not hidden: a reviewer who disagrees with a rejection needs to see the
  107 | /// claim and the evidence that closed it, or the system is asking to be trusted
  108 | /// rather than checked.
  109 | pub fn render(traj: &Trajectory) -> String {
  110 |     let mut out = String::new();
  111 |     let reported: Vec<&Finding> = traj
  112 |         .final_findings
  113 |         .iter()
  114 |         .filter(|f| f.status.is_reported())
  115 |         .collect();
  116 |     let cleared: Vec<&Finding> = traj
  117 |         .final_findings
  118 |         .iter()
